using System.Collections.Concurrent; using SalesManagement.Core.Models; using SalesManagement.Core.Repositories;
namespace SalesManagement.InMemory.Repositories;
public sealed class InMemoryInquiryRepository : InMemoryRepository<CustomerInquiry>, IInquiryRepository { private readonly ConcurrentDictionary<(int,int), int> _seq = new(); public Task<int> NextSequenceAsync(int year, int month, CancellationToken ct = default) => Task.FromResult(_seq.AddOrUpdate((year, month), 1, (_, value) => value + 1)); }
public sealed class InMemoryQuoteRepository : InMemoryRepository<Quote>, IQuoteRepository { private readonly ConcurrentDictionary<(int,int), int> _seq = new(); public Task<int> NextSequenceAsync(int year, int month, CancellationToken ct = default) => Task.FromResult(_seq.AddOrUpdate((year, month), 1, (_, value) => value + 1)); }
public sealed class InMemoryIncotermRepository : InMemoryRepository<Incoterm>, IIncotermRepository { public Task<Incoterm?> FindByCodeAsync(string code, CancellationToken ct = default) { var row = Items.Values.SingleOrDefault(x => x.Code.Equals(code, StringComparison.OrdinalIgnoreCase)); return Task.FromResult(row is null ? null : Clone(row)); } }
